INSERT INTO ui_translations (translation_key, english, telugu) VALUES
('reopen_migration', 'Reopen Migration', 'మైగ్రేషన్ తిరిగి తెరవండి'),
('reopen_migration_note', 'This business has already been started. Reopening lets you enter pre-existing records again. The reason is recorded in the audit log.', 'ఈ వ్యాపారం ఇప్పటికే ప్రారంభమైంది. తిరిగి తెరవడం వల్ల ముందుగా ఉన్న రికార్డులను మళ్లీ నమోదు చేయవచ్చు. కారణం ఆడిట్ లాగ్‌లో నమోదు చేయబడుతుంది.'),
('finish_migration_question', 'Finish Migration?', 'మైగ్రేషన్ ముగించాలా?'),
('finish_migration_note', 'Pre-existing record entry will be closed and the business marked Active. You can reopen migration later if something was missed, but every reopen is recorded.', 'ముందుగా ఉన్న రికార్డుల నమోదు మూసివేయబడుతుంది మరియు వ్యాపారం యాక్టివ్‌గా గుర్తించబడుతుంది. ఏదైనా మిస్ అయితే తర్వాత మైగ్రేషన్ తిరిగి తెరవవచ్చు, కానీ ప్రతి తిరిగి తెరవడం నమోదు చేయబడుతుంది.'),
('finish', 'Finish', 'ముగించండి'),
('add_existing_loan', 'Add Existing Loan', 'ఇప్పటికే ఉన్న రుణం జోడించండి'),
('bulk_onboarding_wizard', 'Bulk Onboarding Wizard', 'బల్క్ ఆన్‌బోర్డింగ్ విజార్డ్'),
('finish_migration', 'Finish Migration', 'మైగ్రేషన్ ముగించండి'),
('could_not_load_migration_status', 'Could Not Load Migration Status', 'మైగ్రేషన్ స్థితి లోడ్ కాలేదు'),
('migration_closed', 'Migration Closed', 'మైగ్రేషన్ మూసివేయబడింది'),
('migration_open', 'Migration Open', 'మైగ్రేషన్ తెరిచి ఉంది'),
('locked', 'Locked', 'లాక్ చేయబడింది'),
('open_status', 'Open', 'తెరిచి ఉంది'),
('migration_locked_note', 'This business was started on {date}. Reopen migration to enter records from the old book.', 'ఈ వ్యాపారం {date}న ప్రారంభమైంది. పాత పుస్తకం నుండి రికార్డులను నమోదు చేయడానికి మైగ్రేషన్ తిరిగి తెరవండి.'),
('an_earlier_date', 'an earlier date', 'ఒక ముందు తేదీ'),
('migration_open_note', 'Enter the loans that were already running when you joined. Each one records what you gave out and what has come back.', 'మీరు చేరినప్పుడు ఇప్పటికే నడుస్తున్న రుణాలను నమోదు చేయండి. ప్రతి ఒక్కటి మీరు ఇచ్చినది మరియు తిరిగి వచ్చినది నమోదు చేస్తుంది.'),
('pre_existing_loans_entered_note', '{count} pre-existing loans entered', '{count} ముందుగా ఉన్న రుణాలు నమోదు చేయబడ్డాయి'),
('declare_opening_bf', 'Declare Opening BF', 'ప్రారంభ BF ప్రకటించండి'),
('change_opening_bf', 'Change Opening BF', 'ప్రారంభ BF మార్చండి'),
('declare_opening_bf_note', 'Count the cash box today and enter that figure. Everything before today is out of scope — the count already reflects it.\n\nThis locks when you finish migration and cannot be changed afterwards.', 'ఈ రోజు నగదు పెట్టెను లెక్కించి ఆ సంఖ్యను నమోదు చేయండి. ఈ రోజుకు ముందు ఉన్నదంతా పరిధిలో లేదు — లెక్క ఇప్పటికే దాన్ని ప్రతిబింబిస్తుంది.\n\nమీరు మైగ్రేషన్ ముగించినప్పుడు ఇది లాక్ అవుతుంది మరియు తర్వాత మార్చలేరు.'),
('cash_in_hand_field', 'Cash in hand *', 'చేతిలో నగదు *'),
('declare', 'Declare', 'ప్రకటించండి'),
('bf_cash_in_hand', 'BF — Cash in Hand', 'BF — చేతిలో నగదు'),
('bf_semantic_label', 'Brought forward, cash in hand', 'ముందుకు తీసుకువచ్చినది, చేతిలో నగదు'),
('bf_declared_on_note', 'Declared on {date}', '{date}న ప్రకటించబడింది'),
('bf_locked_suffix', ' — locked', ' — లాక్ చేయబడింది'),
('bf_not_declared_note', 'Not declared yet. Count the cash box and enter it below.', 'ఇంకా ప్రకటించలేదు. నగదు పెట్టెను లెక్కించి క్రింద నమోదు చేయండి.'),
('line_balance_label', 'Line balance — still with customers', 'లైన్ నిల్వ — ఇంకా కస్టమర్ల వద్ద'),
('line_balance_note', 'Line balance is deliberately outside BF — that money is out on the line, not in the cash box.', 'లైన్ నిల్వ ఉద్దేశపూర్వకంగా BF వెలుపల ఉంది — ఆ డబ్బు లైన్‌లో ఉంది, నగదు పెట్టెలో కాదు.'),
('profit_and_investor_payable', 'Profit & Investor Payable', 'లాభం & పెట్టుబడిదారుకు చెల్లించవలసినది'),
('owed_back_to_investors', 'Owed back to investors', 'పెట్టుబడిదారులకు తిరిగి చెల్లించవలసినది'),
('business_profit', 'Business profit', 'వ్యాపార లాభం'),
('add_existing_loan_note', 'Enter the loan as it stands today. The repayment schedule is created from today forward for whatever is still owed — past instalments are not recreated, so the customer''s Line Score starts from here.', 'రుణాన్ని ఈ రోజు ఉన్నట్లుగా నమోదు చేయండి. ఇంకా బాకీ ఉన్నదానికి ఈ రోజు నుండి తిరిగి చెల్లింపు షెడ్యూల్ సృష్టించబడుతుంది — గత వాయిదాలు తిరిగి సృష్టించబడవు, కాబట్టి కస్టమర్ లైన్ స్కోర్ ఇక్కడి నుండి మొదలవుతుంది.'),
('customer_required_field', 'Customer *', 'కస్టమర్ *'),
